import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  drawTensorGrid,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;
type InitMethod = 'xavier' | 'he' | 'small' | 'truncated';

const W = 1400;
const CX = W / 2;
const BOX_H = 100;
const STEP_GAP = 720;
const BOX_TO_ROW = 400;
const FOOTER_PAD = 70;

const COLORS = {
  xavier: { fill: '#e3f2fd', stroke: '#1565c0' },
  he: { fill: '#ffebee', stroke: '#c62828' },
  small: { fill: '#e8f5e9', stroke: '#2e7d32' },
  truncated: { fill: '#f3e5f5', stroke: '#6a1b9a' },
  weight: { fill: '#f5f5f5', stroke: '#616161' },
  text: { fill: '#e3f2fd', stroke: '#1976d2' },
  muted: 'var(--text-muted)' as string,
};

const METHOD_INFO: Record<InitMethod, { name: string; formula: string; distLabel: string; useCase: string }> = {
  xavier: { name: 'Xavier / Glorot', formula: '√(2/(fan_in+fan_out))', distLabel: 'Uniform[-a, a]', useCase: 'sigmoid / tanh activations' },
  he: { name: 'Kaiming / He', formula: '√(2/fan_in)', distLabel: 'Normal(0, σ²)', useCase: 'ReLU / LeakyReLU activations' },
  small: { name: 'Small Init', formula: '0.02', distLabel: 'Normal(0, 0.02²)', useCase: 'deep residual networks (GPT-2)' },
  truncated: { name: 'Truncated Normal', formula: 'σ=0.02, clip ±2σ', distLabel: 'TruncNorm(0, 0.02²)', useCase: 'prevents outlier weights' },
};

interface WStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void { drawLabel(g as Sel, x, y, text, opts); }

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 120): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 32).attr('cy', y + BOX_H / 2)
    .attr('r', 18).attr('fill', stroke);
  lbl(g, cx - w / 2 + 32, y + BOX_H / 2 + 1, String(sn), { size: 15, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 - 10, title, { size: 16, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 62, y + BOX_H / 2 + 14, formula, { size: 11, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(420, text.length * 7.2 + 40);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 15).attr('width', w).attr('height', 30)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(260, text.length * 6.5 + 32);
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - 13).attr('width', w).attr('height', 26)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function drawTensorBox(g: Gsel, cx: number, cy: number, label: string, sublabel: string,
  w: number, h: number, fill: string, stroke: string): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 2);
  lbl(g, cx, cy - 4, label, { size: 14, weight: '600', color: stroke });
  lbl(g, cx, cy + 14, sublabel, { size: 10, color: COLORS.muted, font: 'monospace' });
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]): WStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ── Distribution helpers ──────────────────────────────────────────────

function makeLCG(seed: number) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) | 0; return ((s >>> 0) / 4294967296); };
}

function sampleInitValue(method: InitMethod, rng: () => number): number {
  const u1 = rng() * 2 - 1;
  if (method === 'xavier') return u1;
  const u2 = rng();
  let z = Math.sqrt(-2 * Math.log(Math.max(u2, 1e-10))) * Math.cos(2 * Math.PI * rng());
  if (method === 'he') return z;
  if (method === 'small') return z * 0.3;
  return Math.max(-1, Math.min(1, z * 0.6));
}

function drawDistribution(g: Gsel, cx: number, cy: number, w: number, h: number,
  method: InitMethod, stroke: string): void {
  const nBars = 32;
  const barW = (w - 4) / nBars;

  g.append('line').attr('x1', cx - w / 2).attr('y1', cy + h)
    .attr('x2', cx + w / 2).attr('y2', cy + h)
    .attr('stroke', '#ccc').attr('stroke-width', 1);

  g.append('line').attr('x1', cx).attr('y1', cy - 4)
    .attr('x2', cx).attr('y2', cy + h + 4)
    .attr('stroke', stroke).attr('stroke-width', 1).attr('stroke-dasharray', '3,3').attr('opacity', 0.5);
  lbl(g, cx, cy - 10, 'μ=0', { size: 8, color: stroke, font: 'monospace' });

  for (let i = 0; i < nBars; i++) {
    const t = (i + 0.5) / nBars;
    const x = (t - 0.5) * 2;
    let density: number;

    if (method === 'xavier') {
      density = Math.abs(x) <= 0.92 ? 0.85 : 0.04;
    } else if (method === 'he') {
      density = Math.exp(-x * x * 2.5);
    } else if (method === 'small') {
      density = Math.exp(-x * x * 10);
    } else {
      density = Math.exp(-x * x * 2.5) * (Math.abs(x) <= 0.65 ? 1 : 0.04);
    }

    const barH = Math.max(1, density * h * 0.85);
    g.append('rect')
      .attr('x', cx - w / 2 + 2 + i * barW).attr('y', cy + h - barH)
      .attr('width', Math.max(1, barW - 1)).attr('height', barH)
      .attr('fill', stroke).attr('opacity', 0.55).attr('rx', 1);
  }
}

function drawInitMatrix(g: Gsel, x: number, y: number, rows: number, cols: number,
  cellSize: number, method: InitMethod, fill: string, stroke: string, label: string): { width: number; height: number } {
  const rng = makeLCG(method === 'xavier' ? 42 : method === 'he' ? 137 : method === 'small' ? 256 : 389);
  return drawTensorGrid(g as Sel, x, y, {
    rows, cols, cellW: cellSize, cellH: cellSize,
    fill, stroke, label, showEllipsis: false,
    cellColors: (_r: number, _c: number) => {
      const val = sampleInitValue(method, rng);
      const t = (val + 1) / 2;
      return d3.interpolate('#fff', stroke)(0.08 + t * 0.55);
    },
  });
}

function drawComputationChain(g: Gsel, cy: number, fanIn: number, fanOut: number, std: number,
  method: InitMethod, color: string): number {
  let boxes: { label: string; sub: string; x: number; w: number }[];

  if (method === 'xavier') {
    const boundVal = std * Math.sqrt(3);
    boxes = [
      { label: 'fan_in', sub: `${fanIn}`, x: CX - 540, w: 120 },
      { label: 'fan_out', sub: `${fanOut}`, x: CX - 370, w: 120 },
      { label: 'sum', sub: `${fanIn + fanOut}`, x: CX - 190, w: 120 },
      { label: '2 ÷ sum', sub: `${(2 / (fanIn + fanOut)).toFixed(5)}`, x: CX + 10, w: 130 },
      { label: '√', sub: std.toFixed(4), x: CX + 200, w: 110 },
      { label: '× √3', sub: `a = ${boundVal.toFixed(4)}`, x: CX + 390, w: 130 },
    ];
  } else if (method === 'he') {
    boxes = [
      { label: 'fan_in', sub: `${fanIn}`, x: CX - 360, w: 140 },
      { label: '2 ÷ fan_in', sub: `${(2 / fanIn).toFixed(5)}`, x: CX - 100, w: 160 },
      { label: '√', sub: std.toFixed(4), x: CX + 180, w: 140 },
    ];
  } else {
    boxes = [];
  }

  for (const box of boxes) {
    g.append('rect').attr('x', box.x - box.w / 2).attr('y', cy - 28).attr('width', box.w).attr('height', 56)
      .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
    lbl(g, box.x, cy - 8, box.label, { size: 10, color, font: 'monospace' });
    lbl(g, box.x, cy + 12, box.sub, { size: 12, weight: '600', color, font: 'monospace' });
  }

  for (let i = 0; i < boxes.length - 1; i++) {
    const x1 = boxes[i].x + boxes[i].w / 2;
    const x2 = boxes[i + 1].x - boxes[i + 1].w / 2;
    drawArrow(g as Sel, x1 + 8, cy, x2 - 8, cy, { color });
  }

  return boxes.length > 0 ? boxes[boxes.length - 1].x + boxes[boxes.length - 1].w / 2 + 30 : CX + 300;
}

// ── Variant: all (comparison) ─────────────────────────────────────────

function renderAllComparison(g: Gsel, startY: number, fanIn: number, fanOut: number): { steps: WStep[]; y: number } {
  const steps: WStep[] = [];
  let y = startY;
  const methods: InitMethod[] = ['xavier', 'he', 'small', 'truncated'];
  const cols = [CX - 420, CX - 140, CX + 140, CX + 420];

  const computeStd = (m: InitMethod): number =>
    m === 'xavier' ? Math.sqrt(2 / (fanIn + fanOut))
    : m === 'he' ? Math.sqrt(2 / fanIn)
    : 0.02;

  const computeBound = (m: InitMethod): number | null =>
    m === 'xavier' ? Math.sqrt(2 / (fanIn + fanOut)) * Math.sqrt(3) : null;

  // Step 1: Target Weight Tensor
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-target', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Target Weight Tensor',
      `W: [${fanIn} × ${fanOut}] — uninitialized`, COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    drawMatrixBlock(gs as Sel, CX - 100, rowY - 70, {
      width: 200, height: 140, label: 'W', sublabel: `[${fanIn} × ${fanOut}]`,
      fill: COLORS.weight.fill, stroke: COLORS.weight.stroke,
      dimTop: `fan_out = ${fanOut}`, dimLeft: `fan_in = ${fanIn}`,
    });

    shapeEq(gs, CX, rowY + 110,
      `weight tensor to initialize: ${fanIn} × ${fanOut} = ${fanIn * fanOut} parameters`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 110 + 38,
      `initialization scale affects gradient flow and training stability`, COLORS.text.stroke);

    y = rowY + 110 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Target', 'Target Weight Tensor',
      `W: [${fanIn} × ${fanOut}]`,
      'The weight tensor W must be initialized before training. The choice of initialization method affects gradient flow, convergence speed, and training stability. Different methods are suited for different activation functions and network architectures.',
      'step-target', COLORS.text.stroke, COLORS.text.fill,
      [`W = torch.empty(${fanIn}, ${fanOut})`, `# Need to initialize before training`]));
  }

  // Step 2: Four Methods — Scale Formulas
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-methods', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Initialization Methods — Scale Factors',
      'Xavier | Kaiming | Small Init | Truncated Normal', COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    for (let i = 0; i < methods.length; i++) {
      const m = methods[i];
      const info = METHOD_INFO[m];
      const c = COLORS[m];
      const std = computeStd(m);
      const bound = computeBound(m);

      gs.append('rect').attr('x', cols[i] - 120).attr('y', rowY - 55).attr('width', 240).attr('height', 110)
        .attr('rx', 8).attr('fill', c.fill).attr('stroke', c.stroke).attr('stroke-width', 2);
      lbl(gs, cols[i], rowY - 32, info.name, { size: 13, weight: '700', color: c.stroke });
      lbl(gs, cols[i], rowY - 8, info.formula, { size: 10, color: c.stroke, font: 'monospace' });

      const stdText = m === 'truncated' ? `σ = ${std.toFixed(4)}` : `σ = ${std.toFixed(4)}`;
      lbl(gs, cols[i], rowY + 14, stdText, { size: 12, weight: '600', color: c.stroke, font: 'monospace' });

      if (bound !== null) {
        lbl(gs, cols[i], rowY + 34, `a = ±${bound.toFixed(4)}`, { size: 10, color: c.stroke, font: 'monospace' });
      } else if (m === 'truncated') {
        lbl(gs, cols[i], rowY + 34, `clip: ±${(std * 2).toFixed(4)}`, { size: 10, color: c.stroke, font: 'monospace' });
      } else {
        lbl(gs, cols[i], rowY + 34, info.distLabel, { size: 9, color: COLORS.muted, font: 'monospace' });
      }
    }

    shapeEq(gs, CX, rowY + 95,
      `each method computes a scale factor σ from fan_in=${fanIn} and fan_out=${fanOut}`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 95 + 38,
      `scale factor determines the range/spread of initial weight values`, COLORS.text.stroke);

    y = rowY + 95 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Methods', 'Initialization Methods',
      'Xavier | Kaiming | Small | Truncated',
      'Four common initialization methods, each designed for different network architectures and activation functions. Xavier preserves variance for linear layers, Kaiming accounts for ReLU halving variance, Small init uses fixed scale for deep residual networks, and Truncated normal prevents outlier weights.',
      'step-methods', COLORS.text.stroke, COLORS.text.fill,
      [`# Xavier uniform`, `nn.init.xavier_uniform_(W, gain=1.0)`, `# Kaiming normal`, `nn.init.kaiming_normal_(W, mode="fan_in", nonlinearity="relu")`, `# Small init (GPT-2)`, `W.data.normal_(mean=0.0, std=0.02)`, `# Truncated normal`, `nn.init.trunc_normal_(W, mean=0.0, std=0.02, a=-0.04, b=0.04)`]));
  }

  // Step 3: Distribution Comparison
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-distributions', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sampling Distributions',
      'how each method distributes initial weight values', COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const histW = 200;
    const histH = 120;

    for (let i = 0; i < methods.length; i++) {
      const m = methods[i];
      const info = METHOD_INFO[m];
      const c = COLORS[m];

      lbl(gs, cols[i], rowY - 15, METHOD_INFO[m].name, { size: 11, weight: '600', color: c.stroke });
      drawDistribution(gs, cols[i], rowY, histW, histH, m, c.stroke);
      lbl(gs, cols[i], rowY + histH + 18, info.distLabel, { size: 9, color: COLORS.muted, font: 'monospace' });
    }

    shapeEq(gs, CX, rowY + histH + 58,
      `Xavier: uniform spread | Kaiming: bell curve | Small: narrow | Truncated: clipped normal`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + histH + 58 + 38,
      `distribution shape determines how weight values are spread across the matrix`, COLORS.text.stroke);

    y = rowY + histH + 58 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Distributions', 'Sampling Distributions',
      'W ~ N(0, σ²) or U(-a, a)',
      'Each method samples weights from a different distribution. Xavier uses uniform for even spread, Kaiming uses normal for bell-curve concentration around zero, Small init uses a very narrow normal, and Truncated normal clips extreme values to prevent outlier weights.',
      'step-distributions', COLORS.text.stroke, COLORS.text.fill,
      [`# Uniform (Xavier)`, `W = torch.empty(fan_in, fan_out).uniform_(-a, a)`, `# Normal (Kaiming/Small)`, `W = torch.empty(fan_in, fan_out).normal_(0, std)`, `# Truncated Normal`, `W = torch.empty(fan_in, fan_out)`, `nn.init.trunc_normal_(W, std=0.02, a=-0.04, b=0.04)`]));
  }

  // Step 4: Resulting Matrices
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-matrices', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Initialized Weight Matrices',
      'visual comparison of weight patterns from each method', COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const cellSize = 8;
    const mRows = 14;
    const mCols = 18;

    for (let i = 0; i < methods.length; i++) {
      const m = methods[i];
      const c = COLORS[m];
      const info = METHOD_INFO[m];

      lbl(gs, cols[i], rowY - 12, info.name, { size: 11, weight: '600', color: c.stroke });
      drawInitMatrix(gs, cols[i] - (mCols * cellSize) / 2, rowY + 4, mRows, mCols, cellSize, m, c.fill, c.stroke, '');
      lbl(gs, cols[i], rowY + mRows * cellSize + 20, `${mRows}×${mCols} view`, { size: 9, color: COLORS.muted, font: 'monospace' });
    }

    shapeEq(gs, CX, rowY + mRows * cellSize + 55,
      `color intensity reflects sampled weight values — each method produces distinct patterns`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + mRows * cellSize + 55 + 38,
      `Xavier: uniform color | Kaiming: varied | Small: faint | Truncated: bounded variation`, COLORS.text.stroke);

    y = rowY + mRows * cellSize + 55 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Matrices', 'Initialized Weight Matrices',
      'W filled with sampled values',
      'Visual comparison shows how each initialization method produces different weight patterns. Xavier creates uniform spread, Kaiming shows bell-curve concentration (more values near zero), Small init produces very small values, and Truncated normal shows bounded variation.',
      'step-matrices', COLORS.text.stroke, COLORS.text.fill,
      [`# After initialization:`, `# Xavier: W ∈ [-a, a] uniformly`, `# Kaiming: W ~ N(0, σ²) normally`, `# Small: W ~ N(0, 0.0004) very small`, `# Truncated: W ∈ [-0.04, 0.04] bounded`]));
  }

  // Step 5: Summary
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-summary', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Summary — When to Use Each Method',
      'matching initialization to architecture and activation', COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    for (let i = 0; i < methods.length; i++) {
      const m = methods[i];
      const info = METHOD_INFO[m];
      const c = COLORS[m];
      const std = computeStd(m);

      gs.append('rect').attr('x', cols[i] - 120).attr('y', rowY - 45).attr('width', 240).attr('height', 90)
        .attr('rx', 8).attr('fill', c.fill).attr('stroke', c.stroke).attr('stroke-width', 1.5);
      lbl(gs, cols[i], rowY - 22, info.name, { size: 12, weight: '700', color: c.stroke });
      lbl(gs, cols[i], rowY + 2, `σ = ${std.toFixed(4)}`, { size: 10, color: c.stroke, font: 'monospace' });
      lbl(gs, cols[i], rowY + 22, info.useCase, { size: 9, color: c.stroke });
    }

    shapeEq(gs, CX, rowY + 80,
      `proper initialization prevents vanishing/exploding gradients and speeds convergence`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 80 + 38,
      `match init method to activation: Xavier→sigmoid, Kaiming→ReLU, Small→deep residual`,
      COLORS.text.stroke);

    y = rowY + 80 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Summary', 'Summary — When to Use',
      'match init to activation & architecture',
      'Xavier/Glorot preserves variance through linear layers — ideal for sigmoid/tanh. Kaiming/He accounts for ReLU halving variance. Small init (GPT-2) uses fixed scale for deep residual stability. Truncated normal prevents outlier weights by resampling values outside ±2σ.',
      'step-summary', COLORS.text.stroke, COLORS.text.fill,
      [`# Choose initialization based on:`, `# 1. Activation function (sigmoid→Xavier, ReLU→Kaiming)`, `# 2. Network depth (deep→Small init for residual stability)`, `# 3. Stability needs (Truncated normal prevents outliers)`]));
  }

  return { steps, y };
}

// ── Variant: single deep dive (parameterized) ───────────────────────

function renderSingleVariant(g: Gsel, startY: number, fanIn: number, fanOut: number,
  method: InitMethod): { steps: WStep[]; y: number } {
  const steps: WStep[] = [];
  let y = startY;
  const info = METHOD_INFO[method];
  const c = COLORS[method];

  const std = method === 'xavier' ? Math.sqrt(2 / (fanIn + fanOut))
    : method === 'he' ? Math.sqrt(2 / fanIn)
    : 0.02;

  // Step 1: Target Weight Tensor
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-target', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Target Weight Tensor',
      `W: [${fanIn} × ${fanOut}] — to be initialized with ${info.name}`,
      COLORS.text.fill, COLORS.text.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    drawMatrixBlock(gs as Sel, CX - 120, rowY - 80, {
      width: 240, height: 160, label: 'W', sublabel: `[${fanIn} × ${fanOut}]`,
      fill: COLORS.weight.fill, stroke: COLORS.weight.stroke,
      dimTop: `fan_out = ${fanOut}`, dimLeft: `fan_in = ${fanIn}`,
    });

    shapeEq(gs, CX, rowY + 120,
      `initializing ${fanIn * fanOut} parameters with ${info.name} method`,
      COLORS.text.stroke);
    sampleNote(gs, CX, rowY + 120 + 38,
      `${info.useCase}`, COLORS.text.stroke);

    y = rowY + 120 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Target', 'Target Weight Tensor',
      `W: [${fanIn} × ${fanOut}]`,
      `The weight tensor W [${fanIn}×${fanOut}] needs to be initialized. ${info.name} initialization is designed for ${info.useCase}.`,
      'step-target', COLORS.text.stroke, COLORS.text.fill,
      [`W = torch.empty(${fanIn}, ${fanOut})`]));
  }

  // Step 2: Compute fan-in & fan-out
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-fan', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Compute fan-in & fan-out',
      `fan_in = shape[0] = ${fanIn}, fan_out = shape[1] = ${fanOut}`,
      c.fill, c.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    drawMatrixBlock(gs as Sel, CX - 180, rowY - 80, {
      width: 200, height: 140, label: 'W', sublabel: `[${fanIn} × ${fanOut}]`,
      fill: c.fill, stroke: c.stroke,
      dimLeft: `fan_in = ${fanIn}`, dimTop: `fan_out = ${fanOut}`,
    });

    const rightX = CX + 240;
    drawTensorBox(gs, rightX, rowY - 30, 'fan_in', `${fanIn} (input dim)`, 180, 50, c.fill, c.stroke);
    drawTensorBox(gs, rightX, rowY + 40, 'fan_out', `${fanOut} (output dim)`, 180, 50, c.fill, c.stroke);

    drawArrow(gs as Sel, CX - 180 + 200 + 16, rowY - 30, rightX - 94, rowY - 30, { color: c.stroke });
    drawArrow(gs as Sel, CX - 180 + 200 + 16, rowY + 40, rightX - 94, rowY + 40, { color: c.stroke });

    shapeEq(gs, CX, rowY + 110,
      `fan_in = W.shape[0] = ${fanIn}, fan_out = W.shape[1] = ${fanOut}`,
      c.stroke);
    sampleNote(gs, CX, rowY + 110 + 38,
      `fan_in: number of input units, fan_out: number of output units`, c.stroke);

    y = rowY + 110 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Fan-in/out', 'Compute fan-in & fan-out',
      `fan_in = ${fanIn}, fan_out = ${fanOut}`,
      'fan-in is the number of input connections (rows), fan-out is the number of output connections (columns). These determine the scale factor for initialization — larger fan values produce smaller initial weights to preserve variance.',
      'step-fan', c.stroke, c.fill,
      [`fan_in = W.shape[0]  # ${fanIn}`, `fan_out = W.shape[1]  # ${fanOut}`]));
  }

  // Step 3: Scale Factor Computation
  {
    const stepId = 3;
    const formulaStr = method === 'xavier' ? 'std = √(2/(fan_in+fan_out))'
      : method === 'he' ? 'std = √(2/fan_in)'
      : method === 'small' ? 'std = 0.02 (fixed)'
      : 'std = 0.02, clip ±2σ';
    const gs = startGroup(g, 'step-scale', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Compute Scale Factor',
      formulaStr, c.fill, c.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    if (method === 'xavier' || method === 'he') {
      drawComputationChain(gs, rowY, fanIn, fanOut, std, method, c.stroke);

      const chainBottom = rowY + 45;
      const formulaText = method === 'xavier'
        ? `std = √(2/(${fanIn}+${fanOut})) = √(${(2 / (fanIn + fanOut)).toFixed(5)}) = ${std.toFixed(4)}`
        : `std = √(2/${fanIn}) = √(${(2 / fanIn).toFixed(5)}) = ${std.toFixed(4)}`;
      lbl(gs, CX, chainBottom + 20, formulaText, { size: 11, color: c.stroke, font: 'monospace' });

      if (method === 'xavier') {
        const boundVal = std * Math.sqrt(3);
        lbl(gs, CX, chainBottom + 42, `uniform bound: a = std × √3 = ${std.toFixed(4)} × 1.7321 = ${boundVal.toFixed(4)}`,
          { size: 10, color: COLORS.muted, font: 'monospace' });
      }

      shapeEq(gs, CX, chainBottom + 70, formulaText, c.stroke);
      sampleNote(gs, CX, chainBottom + 70 + 38,
        method === 'xavier' ? `samples from U(-${(std * Math.sqrt(3)).toFixed(4)}, ${(std * Math.sqrt(3)).toFixed(4)})` : `samples from N(0, ${std.toFixed(4)}²)`,
        c.stroke);
      y = chainBottom + 70 + 38 + 30 + STEP_GAP;
    } else if (method === 'small') {
      const boxes = [
        { label: 'std', sub: '0.02', x: CX - 220, w: 140 },
        { label: '÷ √n_layers', sub: `0.02 / √L`, x: CX + 30, w: 170 },
        { label: 'result', sub: std.toFixed(4), x: CX + 290, w: 140 },
      ];
      for (const box of boxes) {
        gs.append('rect').attr('x', box.x - box.w / 2).attr('y', rowY - 28).attr('width', box.w).attr('height', 56)
          .attr('rx', 6).attr('fill', '#fff').attr('stroke', c.stroke).attr('stroke-width', 1.5);
        lbl(gs, box.x, rowY - 8, box.label, { size: 10, color: c.stroke, font: 'monospace' });
        lbl(gs, box.x, rowY + 12, box.sub, { size: 12, weight: '600', color: c.stroke, font: 'monospace' });
      }
      for (let i = 0; i < boxes.length - 1; i++) {
        const x1 = boxes[i].x + boxes[i].w / 2;
        const x2 = boxes[i + 1].x - boxes[i + 1].w / 2;
        drawArrow(gs as Sel, x1 + 8, rowY, x2 - 8, rowY, { color: c.stroke });
      }

      const chainBottom = rowY + 45;
      lbl(gs, CX, chainBottom + 20, `GPT-2 style: fixed std = 0.02, optionally scaled by 1/√(n_layers)`, { size: 10, color: COLORS.muted, font: 'monospace' });

      shapeEq(gs, CX, chainBottom + 50,
        `fixed scale ensures stable gradients in deep residual networks`,
        c.stroke);
      sampleNote(gs, CX, chainBottom + 50 + 38,
        `GPT-2: std = 0.02 / √n_layers for n_layers residual blocks`,
        c.stroke);
      y = chainBottom + 50 + 38 + 30 + STEP_GAP;
    } else {
      const boxes = [
        { label: 'σ', sub: '0.02', x: CX - 320, w: 120 },
        { label: 'N(0, σ²)', sub: 'sample', x: CX - 120, w: 130 },
        { label: 'clip ±2σ', sub: `±${(std * 2).toFixed(4)}`, x: CX + 100, w: 140 },
        { label: 'resample', sub: 'if outside', x: CX + 310, w: 130 },
      ];
      for (const box of boxes) {
        gs.append('rect').attr('x', box.x - box.w / 2).attr('y', rowY - 28).attr('width', box.w).attr('height', 56)
          .attr('rx', 6).attr('fill', '#fff').attr('stroke', c.stroke).attr('stroke-width', 1.5);
        lbl(gs, box.x, rowY - 8, box.label, { size: 10, color: c.stroke, font: 'monospace' });
        lbl(gs, box.x, rowY + 12, box.sub, { size: 12, weight: '600', color: c.stroke, font: 'monospace' });
      }
      for (let i = 0; i < boxes.length - 1; i++) {
        const x1 = boxes[i].x + boxes[i].w / 2;
        const x2 = boxes[i + 1].x - boxes[i + 1].w / 2;
        drawArrow(gs as Sel, x1 + 8, rowY, x2 - 8, rowY, { color: c.stroke });
      }

      const chainBottom = rowY + 45;
      lbl(gs, CX, chainBottom + 20, `truncation prevents extreme weight values that could destabilize training`, { size: 10, color: COLORS.muted, font: 'monospace' });

      shapeEq(gs, CX, chainBottom + 50,
        `clip range: [-2σ, 2σ] = [-${(std * 2).toFixed(4)}, ${(std * 2).toFixed(4)}]`,
        c.stroke);
      sampleNote(gs, CX, chainBottom + 50 + 38,
        `values outside clip range are resampled from N(0, σ²)`,
        c.stroke);
      y = chainBottom + 50 + 38 + 30 + STEP_GAP;
    }

    steps.push(makeStep(stepId, 'Scale', 'Compute Scale Factor', formulaStr,
      `The scale factor σ = ${std.toFixed(4)} determines the spread of initial weights. ${method === 'xavier' ? 'Xavier uses the harmonic mean of fan_in and fan_out.' : method === 'he' ? 'Kaiming uses only fan_in, accounting for ReLU halving variance.' : method === 'small' ? 'Small init uses a fixed scale suitable for deep networks.' : 'Truncated normal clips outliers at ±2σ.'}`,
      'step-scale', c.stroke, c.fill,
      method === 'xavier' ? [`std = math.sqrt(2.0 / (${fanIn} + ${fanOut}))`, `# std = ${std.toFixed(4)}`, `a = std * math.sqrt(3)`, `# a = ${(std * Math.sqrt(3)).toFixed(4)}`]
      : method === 'he' ? [`std = math.sqrt(2.0 / ${fanIn})`, `# std = ${std.toFixed(4)}`]
      : method === 'small' ? [`std = 0.02  # GPT-2 style`]
      : [`std = 0.02`, `a, b = -0.04, 0.04  # clip bounds`]));
  }

  // Step 4: Sampling Distribution
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-distribution', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Sampling Distribution',
      info.distLabel, c.fill, c.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    lbl(gs, CX, rowY - 15, `${info.name}: ${info.distLabel}`, { size: 13, weight: '600', color: c.stroke });

    const histW = 600;
    const histH = 140;
    drawDistribution(gs, CX, rowY + 5, histW, histH, method, c.stroke);

    const distBottom = rowY + histH + 25;
    if (method === 'xavier') {
      const a = std * Math.sqrt(3);
      lbl(gs, CX - histW / 2 + 20, distBottom, `-a = -${a.toFixed(4)}`, { size: 9, color: c.stroke, font: 'monospace', anchor: 'start' });
      lbl(gs, CX + histW / 2 - 20, distBottom, `+a = ${a.toFixed(4)}`, { size: 9, color: c.stroke, font: 'monospace', anchor: 'end' });
      lbl(gs, CX, distBottom + 20, `uniform: all values equally likely within [-a, a]`, { size: 10, color: COLORS.muted, font: 'monospace' });
    } else if (method === 'truncated') {
      lbl(gs, CX - histW / 4, distBottom, `-2σ = -${(std * 2).toFixed(4)}`, { size: 9, color: c.stroke, font: 'monospace' });
      lbl(gs, CX + histW / 4, distBottom, `+2σ = ${(std * 2).toFixed(4)}`, { size: 9, color: c.stroke, font: 'monospace' });
      lbl(gs, CX, distBottom + 20, `values outside ±2σ are resampled (truncated)`, { size: 10, color: COLORS.muted, font: 'monospace' });
    } else {
      lbl(gs, CX, distBottom, `σ = ${std.toFixed(4)}`, { size: 10, color: c.stroke, font: 'monospace' });
      const spread = method === 'small' ? 'narrow: values concentrated near zero' : 'bell curve: most values near zero, tails decay';
      lbl(gs, CX, distBottom + 20, spread, { size: 10, color: COLORS.muted, font: 'monospace' });
    }

    shapeEq(gs, CX, distBottom + 48,
      `sample ${fanIn * fanOut} values from ${info.distLabel}`,
      c.stroke);
    sampleNote(gs, CX, distBottom + 48 + 38,
      `each weight independently sampled — no correlation between positions`,
      c.stroke);

    y = distBottom + 48 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Distribution', 'Sampling Distribution', info.distLabel,
      `Weights are sampled independently from ${info.distLabel}. ${method === 'xavier' ? 'Uniform distribution gives equal probability to all values in the range.' : method === 'he' ? 'Normal distribution concentrates values near zero with decaying tails.' : method === 'small' ? 'Very narrow distribution produces small initial weights for residual stability.' : 'Truncated normal resamples any value outside the clip range, preventing outlier weights.'}`,
      'step-distribution', c.stroke, c.fill,
      method === 'xavier' ? [`W = torch.empty(${fanIn}, ${fanOut}).uniform_(-${(std * Math.sqrt(3)).toFixed(4)}, ${(std * Math.sqrt(3)).toFixed(4)})`]
      : [`W = torch.empty(${fanIn}, ${fanOut}).normal_(0, ${std.toFixed(4)})`]));
  }

  // Step 5: Result Matrix
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-result', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Initialized Weight Matrix',
      `W ~ ${info.distLabel}`, c.fill, c.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    lbl(gs, CX, rowY - 12, `${info.name}: Initialized W [${fanIn}×${fanOut}]`, { size: 13, weight: '600', color: c.stroke });

    const cellSize = 10;
    const mRows = 20;
    const mCols = 28;
    const gridW = mCols * cellSize;
    drawInitMatrix(gs, CX - gridW / 2, rowY + 4, mRows, mCols, cellSize, method, c.fill, c.stroke, '');

    const gridBottom = rowY + mRows * cellSize + 20;
    lbl(gs, CX, gridBottom, `showing ${mRows}×${mCols} = ${mRows * mCols} of ${fanIn * fanOut} values`, { size: 9, color: COLORS.muted, font: 'monospace' });

    const statText = method === 'xavier'
      ? `range: [±${(std * Math.sqrt(3)).toFixed(4)}], mean ≈ 0, std ≈ ${std.toFixed(4)}`
      : method === 'truncated'
      ? `range: [±${(std * 2).toFixed(4)}], mean ≈ 0, std ≈ ${std.toFixed(4)}`
      : `mean ≈ 0, std ≈ ${std.toFixed(4)}`;

    shapeEq(gs, CX, gridBottom + 30, statText, c.stroke);
    sampleNote(gs, CX, gridBottom + 30 + 38,
      `${info.useCase} — ${info.name} preserves gradient variance through this layer`,
      c.stroke);

    y = gridBottom + 30 + 38 + 30 + STEP_GAP;
    steps.push(makeStep(stepId, 'Result', 'Initialized Weight Matrix',
      `W ~ ${info.distLabel}`,
      `The initialized weight matrix W [${fanIn}×${fanOut}] with values sampled from ${info.distLabel}. Color intensity represents value magnitude — darker cells have larger absolute values. This initialization ensures stable gradient flow during early training.`,
      'step-result', c.stroke, c.fill,
      [`# W is now initialized:`, `# shape: [${fanIn}, ${fanOut}]`, `# ${statText}`, `# Ready for forward pass`]));
  }

  return { steps, y };
}

// ── Main entry point ──────────────────────────────────────────────────

export function renderWeightInitDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const fanIn = Number(params.d_model) || 512;
  const fanOut = Number(params.d_model) || 512;
  const variant = String(params.variant || 'all') as 'all' | InitMethod;

  const stepsMeta: WStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Weight Initialization', { size: 18, weight: '700', color: 'var(--text)' });
  lbl(g, CX, y + 36, 'Xavier / Kaiming / Small Init / Truncated Normal scaling strategies', { size: 11, color: COLORS.muted });
  y += 56;

  const { steps, y: finalY } = variant === 'all'
    ? renderAllComparison(g, y, fanIn, fanOut)
    : renderSingleVariant(g, y, fanIn, fanOut, variant as InitMethod);
  stepsMeta.push(...steps);
  y = finalY;

  const insightText = variant === 'all'
    ? 'Weight initialization sets the starting point for optimization. Xavier/Glorot preserves variance for linear layers (sigmoid/tanh), Kaiming/He accounts for ReLU halving variance, Small init (GPT-2) uses fixed scale for deep residual stability, and Truncated normal prevents outlier weights.'
    : variant === 'xavier'
    ? 'Xavier (Glorot) initialization preserves signal variance through linear layers by setting std = sqrt(2/(fan_in+fan_out)). The uniform variant uses bounds ±std*sqrt(3). Ideal for sigmoid and tanh activations where symmetric, bounded initialization helps avoid saturation.'
    : variant === 'he'
    ? 'Kaiming (He) initialization accounts for the fact that ReLU halves the variance of its input by using std = sqrt(2/fan_in). This compensates for the dead-zone effect of ReLU, maintaining signal variance through deep networks.'
    : variant === 'small'
    ? 'Small initialization (GPT-2 style) uses a fixed std of 0.02, optionally scaled by 1/sqrt(n_layers). This conservative approach stabilizes training in very deep residual networks where accumulated residual additions can amplify variance.'
    : 'Truncated normal initialization samples from N(0, σ²) but resamples any value outside [-2σ, 2σ]. This prevents extreme outlier weights that could cause gradient explosion in early training while maintaining the benefits of normal distribution sampling.';

  const perfText = `Initialization is O(fan_in × fan_out) — negligible compared to training. But choice of method significantly affects convergence: wrong init can cause vanishing gradients (too small) or exploding gradients (too large).`;

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'backpropagation', 'Backpropagation');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'activation-functions', 'Activation Functions');
  y += 80;

  const codeLines = variant === 'all'
    ? [
      'import torch.nn as nn', 'import math', '',
      '# Xavier (Glorot) uniform — for sigmoid/tanh',
      'nn.init.xavier_uniform_(W, gain=1.0)', '',
      '# Kaiming (He) normal — for ReLU',
      'nn.init.kaiming_normal_(W, mode="fan_in", nonlinearity="relu")', '',
      '# Small init (GPT-2 style) — for deep residual',
      'W.data.normal_(mean=0.0, std=0.02 / math.sqrt(n_layers))', '',
      '# Truncated normal — prevents outliers',
      'nn.init.trunc_normal_(W, mean=0.0, std=0.02, a=-0.04, b=0.04)',
    ]
    : variant === 'xavier'
    ? [`fan_in, fan_out = ${fanIn}, ${fanOut}`, `std = math.sqrt(2.0 / (fan_in + fan_out))  # ${Math.sqrt(2 / (fanIn + fanOut)).toFixed(4)}`, `a = std * math.sqrt(3)  # ${(Math.sqrt(2 / (fanIn + fanOut)) * Math.sqrt(3)).toFixed(4)}`, `W = torch.empty(fan_in, fan_out).uniform_(-a, a)`]
    : variant === 'he'
    ? [`fan_in = ${fanIn}`, `std = math.sqrt(2.0 / fan_in)  # ${Math.sqrt(2 / fanIn).toFixed(4)}`, `W = torch.empty(fan_in, ${fanOut}).normal_(0, std)`]
    : variant === 'small'
    ? [`std = 0.02  # GPT-2 default`, `# optionally: std = 0.02 / math.sqrt(n_layers)`, `W = torch.empty(${fanIn}, ${fanOut}).normal_(0, std)`]
    : [`std = 0.02`, `W = torch.empty(${fanIn}, ${fanOut})`, `nn.init.trunc_normal_(W, mean=0.0, std=std, a=-2*std, b=2*std)`, `# values outside [-0.04, 0.04] are resampled`];

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    `Weight Initialization — ${variant === 'all' ? 'All Methods' : METHOD_INFO[variant as InitMethod].name}`,
    [`variant: ${variant === 'all' ? 'comparison' : variant}`],
    codeLines);

  return { width: W, height: y + FOOTER_PAD, steps: stepsMeta };
}
